script:
(function () {
  'use strict';
  // Business forecast: project revenue, then costs and profit, year by year.
  //   Growth mode: revenue in forecast year k = R0 * (1 + g)^k.
  //   Trend mode: least-squares straight line through the past figures (x = 1..m, oldest first):
  //     slope b = sum((x - xbar)(y - ybar)) / sum((x - xbar)^2), a = ybar - b * xbar,
  //     revenue in forecast year k = a + b * (m + k), floored at $0.
  //   Cost of revenue % in year k = base % + k * yearly change (floored at 0); operating expenses
  //   are a % of revenue; fixed costs grow at their own rate, fixed_k = F * (1 + gf)^k.
  //   Pre-tax profit = revenue - cost of revenue - operating expenses - fixed; tax = rate * max(0, pre-tax).
  //   Average yearly growth = (final revenue / starting revenue)^(1 / years) - 1.
  // Verified in Node (scratchpad tests/b2biz), hand-checked: $500,000 growing 8% -> year 5
  //   $734,664.04 (= 500,000 * 1.08^5); with 45% cost and 30% opex the year-5 profit is $183,666.01
  //   (25% margin). Trend through 320k, 365k, 400k, 450k, 500k -> slope $44,500/yr, next year
  //   $540,500, year 5 $718,500; trend through 100, 200 -> 300, 400. A falling trend floors at $0 with
  //   a warning; blank gaps, negative or out-of-range input show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });

  // --- calc ---
  function fitLine(ys) {
    var m = ys.length, xbar = (m + 1) / 2, ybar = 0, sxy = 0, sxx = 0, i;
    for (i = 0; i < m; i++) ybar += ys[i] / m;
    for (i = 0; i < m; i++) { sxy += (i + 1 - xbar) * (ys[i] - ybar); sxx += (i + 1 - xbar) * (i + 1 - xbar); }
    var b = sxx > 0 ? sxy / sxx : 0;
    return { slope: b, intercept: ybar - b * xbar, m: m };
  }

  function forecast(o) {
    // o: mode, revenue, growth, past[], years, cost, costStep, opex, fixed, fixedGrowth, tax (rates as decimals)
    var rows = [], floored = false, line = null, start;
    if (o.mode === 'trend') { line = fitLine(o.past); start = o.past[o.past.length - 1]; }
    else start = o.revenue;
    for (var k = 1; k <= o.years; k++) {
      var rev;
      if (line) {
        rev = line.intercept + line.slope * (line.m + k);
        if (rev < 0) { rev = 0; floored = true; }
      } else rev = o.revenue * Math.pow(1 + o.growth, k);
      var costPct = Math.max(0, o.cost + o.costStep * k);
      var cost = rev * costPct, opex = rev * o.opex, fixed = o.fixed * Math.pow(1 + o.fixedGrowth, k);
      var pretax = rev - cost - opex - fixed, tax = Math.max(0, pretax) * o.tax;
      rows.push({ k: k, revenue: rev, costPct: costPct, cost: cost, gross: rev - cost, overhead: opex + fixed,
                  pretax: pretax, tax: tax, net: pretax - tax, margin: rev > 0 ? (pretax - tax) / rev : null });
    }
    var totRev = 0, totNet = 0;
    rows.forEach(function (r) { totRev += r.revenue; totNet += r.net; });
    var final = rows[rows.length - 1];
    var cagr = start > 0 && final.revenue > 0 ? Math.pow(final.revenue / start, 1 / o.years) - 1 : null;
    var pastCagr = null;
    if (line && o.past[0] > 0 && start > 0) pastCagr = Math.pow(start / o.past[0], 1 / (o.past.length - 1)) - 1;
    return { rows: rows, totalRevenue: totRev, totalNet: totNet, cagr: cagr, line: line, pastCagr: pastCagr, floored: floored };
  }
  // --- end calc ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pct(x) { return x === null ? 'n/a' : one.format(x * 100) + '%'; }

  var OUT = ['bfFinalRev', 'bfFinalProfit', 'bfTotalProfit', 'bfTotalRev', 'bfCagr', 'bfFinalMargin', 'bfSlope', 'bfPastCagr'];

  function readPast() {
    var vals = [], seen = false;
    for (var i = 1; i <= 5; i++) {
      var raw = String(el('bfPast' + i).value).trim();
      if (raw === '') { if (seen) return 'gap'; continue; }
      var v = Number(raw);
      if (!isFinite(v) || v < 0) return 'bad';
      seen = true;
      vals.push(v);
    }
    return vals;
  }

  function update() {
    var trend = el('bfModeTrend').checked;
    el('bfGrowthBox').hidden = trend;
    el('bfTrendBox').hidden = !trend;
    el('bfSlopeRow').hidden = !trend;
    el('bfPastCagrRow').hidden = !trend;
    var lastYear = read('bfLastYear'), years = read('bfYears');
    var validYear = !isNaN(lastYear) && lastYear % 1 === 0 && lastYear >= 1900 && lastYear <= 2200;
    for (var i = 1; i <= 5; i++) setText('bfPast' + i + 'Label', validYear ? String(lastYear - 5 + i) : (i === 5 ? 'Latest year' : (5 - i) + ' years earlier'));

    var o = {
      mode: trend ? 'trend' : 'growth', revenue: read('bfRevenue'), growth: read('bfGrowth', true) / 100,
      years: years, cost: read('bfCost', true) / 100, costStep: read('bfCostStep', true) / 100,
      opex: read('bfOpex', true) / 100, fixed: read('bfFixed', true), fixedGrowth: read('bfFixedGrowth', true) / 100,
      tax: read('bfTax', true) / 100
    };
    var msg = '', past = trend ? readPast() : null;
    if (!validYear) msg = 'Enter the latest full year as a four-digit year.';
    else if (isNaN(years) || years % 1 !== 0 || years < 1 || years > 50) msg = 'Enter 1 to 50 whole years to forecast.';
    else if (!trend && (isNaN(o.revenue) || o.revenue < 0)) msg = 'Enter the latest year\'s revenue of $0 or more.';
    else if (!trend && (isNaN(o.growth) || o.growth < -0.99 || o.growth > 10)) msg = 'Enter a growth rate from -99% to 1,000%.';
    else if (trend && past === 'gap') msg = 'Fill in every year from the oldest figure you have up to the latest year. Only the oldest years can be left blank.';
    else if (trend && past === 'bad') msg = 'Past revenue figures cannot be negative.';
    else if (trend && past.length < 2) msg = 'Enter revenue for at least two years, including the latest year.';
    else if ([o.cost, o.opex].some(function (v) { return isNaN(v) || v < 0 || v > 10; })) msg = 'Enter cost percentages from 0% to 1,000% of revenue.';
    else if (isNaN(o.costStep) || o.costStep < -1 || o.costStep > 1) msg = 'Enter a yearly change in cost of revenue from -100 to 100 percentage points.';
    else if (isNaN(o.fixed) || o.fixed < 0) msg = 'Fixed costs cannot be negative.';
    else if (isNaN(o.fixedGrowth) || o.fixedGrowth < -0.99 || o.fixedGrowth > 1) msg = 'Enter fixed cost growth from -99% to 100%.';
    else if (isNaN(o.tax) || o.tax < 0 || o.tax > 1) msg = 'Enter a tax rate from 0% to 100%.';
    var error = el('bfError'), warn = el('bfWarning');
    error.hidden = !msg;
    error.textContent = msg;
    warn.hidden = true;
    if (msg) { OUT.forEach(function (id) { setText(id, '–'); }); el('bfTable').textContent = ''; return; }
    if (trend) o.past = past;

    var r = forecast(o);
    var final = r.rows[r.rows.length - 1];
    var finalYear = lastYear + years;
    setText('bfFinalRevLabel', 'Revenue in ' + finalYear);
    setText('bfFinalProfitLabel', (o.tax > 0 ? 'Net profit in ' : 'Pre-tax profit in ') + finalYear);
    setText('bfFinalRev', money.format(final.revenue));
    setText('bfFinalProfit', money.format(final.net));
    setText('bfTotalProfit', money.format(r.totalNet));
    setText('bfTotalRev', money.format(r.totalRevenue));
    setText('bfCagr', pct(r.cagr));
    setText('bfFinalMargin', pct(final.margin));
    setText('bfSlope', r.line ? (r.line.slope >= 0 ? '+' : '−') + money.format(Math.abs(r.line.slope)) : '–');
    setText('bfPastCagr', r.line ? pct(r.pastCagr) : '–');

    var notes = [];
    if (r.floored) notes.push('The past figures trend downward steeply enough that the straight line falls below zero, so revenue is shown as $0 from that point.');
    if (r.rows.some(function (row) { return row.pretax < 0; })) notes.push('Costs exceed revenue in at least one year, so the forecast shows a loss there.');
    warn.hidden = notes.length === 0;
    setText('bfWarningText', notes.join(' '));

    var body = el('bfTable');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(lastYear + row.k), money.format(row.revenue), money.format(row.cost) + ' (' + one.format(row.costPct * 100) + '%)',
       money.format(row.gross), money.format(row.overhead), money.format(row.pretax), money.format(row.tax),
       money.format(row.net), pct(row.margin)].forEach(function (text) {
        var td = document.createElement('td');
        td.textContent = text;
        tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('bfForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
